import {HARMONICS} from './voice-dsp.mjs';
import {PARTICLES} from './mouth-dsp.mjs';
export function distanceToSegment(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,l=dx*dx+dy*dy;const t=l?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/l)):0;return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy)}
export function distanceToAnchor(p,a){const points=a.points;if(points.length===1)return Math.hypot(p.x-points[0].x,p.y-points[0].y);let d=Infinity;for(let i=1;i<points.length;i++)d=Math.min(d,distanceToSegment(p,points[i-1],points[i]));return d}
export function weightsAt(anchors,p){if(!anchors.length)return [];const distances=anchors.map(a=>distanceToAnchor(p,a)),exact=distances.map(d=>d<1e-6),hits=exact.filter(Boolean).length;if(hits)return exact.map(x=>x?1/hits:0);const nearest=Math.min(...distances);const scores=distances.map(d=>(nearest/d)**2),sum=scores.reduce((s,v)=>s+v,0);return scores.map(v=>v/sum)}
export function synthModel(anchors,weights,position){
 if(position){const expanded=[],expandedWeights=[];for(let i=0;i<anchors.length;i++){for(const f of modelsAtAnchor(anchors[i],position)){expanded.push({model:f.model});expandedWeights.push(weights[i]*f.weight)}}return synthModel(expanded,expandedWeights)}const frequencies=new Float32Array(PARTICLES),amplitudes=new Float32Array(HARMONICS);let voiceWeight=0,noiseWeight=0,logPitch=0;for(let i=0;i<anchors.length;i++){const m=anchors[i].model,w=weights[i];if(m.voice){voiceWeight+=w;logPitch+=w*Math.log(m.voice.pitch)}else noiseWeight+=w}
 if(voiceWeight>1e-10){for(let h=0;h<HARMONICS;h++){let logAmp=0;for(let i=0;i<anchors.length;i++)if(anchors[i].model.voice)logAmp+=weights[i]/voiceWeight*Math.log(Math.max(anchors[i].model.voice.amplitudes[h],1e-5));amplitudes[h]=Math.exp(logAmp)}let energy=amplitudes.reduce((s,a)=>s+a*a,0);const gain=.18*Math.SQRT2/Math.sqrt(energy||1);for(let h=0;h<HARMONICS;h++)amplitudes[h]*=gain}
 if(noiseWeight>1e-10)for(let i=0;i<anchors.length;i++)if(!anchors[i].model.voice)for(let v=0;v<PARTICLES;v++)frequencies[v]+=anchors[i].model.frequencies[v]*weights[i]/noiseWeight;
 return{pitch:voiceWeight>1e-10?Math.exp(logPitch/voiceWeight):145,amplitudes,frequencies,voicing:voiceWeight};}

// Project onto the whole polyline, retaining both segment position and drawing time.
export function projectToAnchor(p,a){const points=a.points;if(points.length<2)return{point:points[0],fraction:0,time:0,distance:Math.hypot(p.x-points[0].x,p.y-points[0].y)};const lengths=[];let total=0;for(let i=1;i<points.length;i++){const l=Math.hypot(points[i].x-points[i-1].x,points[i].y-points[i-1].y);lengths.push(l);total+=l}let cumulative=0,best=null;for(let i=1;i<points.length;i++){const x=points[i-1],y=points[i],dx=y.x-x.x,dy=y.y-x.y,l=dx*dx+dy*dy,t=l?Math.max(0,Math.min(1,((p.x-x.x)*dx+(p.y-x.y)*dy)/l)):0,point={x:x.x+dx*t,y:x.y+dy*t},distance=Math.hypot(p.x-point.x,p.y-point.y);const fraction=(cumulative+t*lengths[i-1])/(total||1);const time=Number.isFinite(x.t)&&Number.isFinite(y.t)?x.t+(y.t-x.t)*t:fraction*(a.trajectory?.duration||a.audio?.channels?.[0]?.length/a.audio?.rate||0);if(!best||distance<best.distance)best={point,fraction,time,distance,segment:i-1};cumulative+=lengths[i-1]}return best}
export function modelsAtAnchor(a,p){const frames=a.trajectory?.frames;if(!frames?.length)return[{model:a.model,weight:1}];const time=projectToAnchor(p,a).time;if(time<=frames[0].time)return[{model:frames[0].model,weight:1}];const last=frames.at(-1);if(time>=last.time)return[{model:last.model,weight:1}];let low=0,high=frames.length-1;while(high-low>1){const mid=(low+high)>>1;if(frames[mid].time<=time)low=mid;else high=mid}const t=(time-frames[low].time)/(frames[high].time-frames[low].time);return[{model:frames[low].model,weight:1-t},{model:frames[high].model,weight:t}]}
